// Closing a work order: MAIN site only, and only with a recent human approval
// that was confirmed in this session by a completed Kelvora lookup.
// ASSUMPTION: Kelvora declares decision and approver_kind as plain strings, so
// "GRANTED" and "HUMAN" are assumed to be the values it uses (as in Wexlow's enums).
@id("close-workorder-with-recent-human-approval")
permit (principal, action == Drupe::Action::"MaintData___close_workorder", resource)
when { context.input.site_id == "MAIN" }
when temporal {
  formerly within 1h Drupe::Action::"Kelvora___get_approval"::response{
    eventResource: resource,
    input.site_id: context.input.site_id,
    input.wonum: context.input.wonum,
    output.decision: "GRANTED",
    output.approver_kind: "HUMAN"
  }
};

// The approval lookup must itself be permitted, otherwise its response is never recorded.
@id("allow-kelvora-approval-lookup")
permit (principal, action == Drupe::Action::"Kelvora___get_approval", resource);

// Other read-only lookups. Wexlow approvals are readable but never count towards a close.
@id("allow-read-only-lookups")
permit (principal, action in [
  Drupe::Action::"Wexlow___get_approval",
  Drupe::Action::"MaintData___get_workorder",
  Drupe::Action::"MaintData___list_workorders",
  Drupe::Action::"MaintData___get_my_assigned_workorders",
  Drupe::Action::"MaintData___get_schedule_calendar",
  Drupe::Action::"MaintData___get_failure_codes",
  Drupe::Action::"MaintData___get_workorder_actuals_vs_planned",
  Drupe::Action::"MaintData___get_workorder_costs",
  Drupe::Action::"MaintData___get_workorder_kpis",
  Drupe::Action::"MaintData___get_workorder_tasks"
], resource);

// The agent can never approve work orders (explicit backstop; also denied by default).
@id("never-approve-workorders")
forbid (principal, action == Drupe::Action::"MaintData___approve_workorder", resource);
```

